    def __init__(self, lst):
        self.votes = {}
        for item in lst:
            self.votes[item] = 0

    def cast_vote(self, candidate):
        if candidate in self.votes:
            self.votes[candidate] += 1
            return True
        else:
            return False

    def get_votes(self, candidate):
        return self.votes[candidate]

    def get_winner(self):
        M = max(self.votes.values())
        tied = []
        for k, v in self.votes.items():
            if v == M:
                tied.append((k, v))
        if len(tied) > 1:
            return "tie"
        else:
            return tied[0][0]

